 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC308 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc308_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc308_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc308_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 CREATE TEMPORARY TABLE rrc308_peer_recipes LIKE tradeskill_recipe;
